string private name;
uint256 private score;

function getProfile() external view
    returns (string memory profileName, uint256 profileScore)
{
    return (name, score);
}

function classify(uint256 score)
    external pure returns (bool passed, string memory level)
{
    passed = score >= 60;
    level = score >= 90 ? "A" : "B";
}
